using System;using System.Linq;using UnityEngine;using IndianOceanAssets.ShooterSurvival;
public static class ProbeBehaviorCycle02{public static object Main(){var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();return new{Time.frameCount,Time.time,Time.timeScale,TimeManager.isGameRunning,TimeManager.timeFactor,CanvasScript.isGameOver,d.Running,d.Elapsed,d.Distance,d.CurrentFloor,hp=d.Player.currentHealth,playerEnabled=d.Player.enabled,encounters=d.encounters.Where(e=>e.Activated&&!e.Complete).Select(e=>new{e.name,e.Activated,e.Complete,actors=e.actors.Select(a=>new{a.name,a.gameObject.activeInHierarchy,a.IsDead,role=a.GetComponent<Chapter45RoleAction>()?.role.ToString(),canAct=a.GetComponent<Chapter45RoleAction>()?.CanAct}).ToArray()}).ToArray()};}}
